 CREATE TEMPORARY TABLE rrc209_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc209_before LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc209_after LIKE tradeskill_recipe_entries;
