 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries a JOIN tradeskill_recipe r ON r.id=a.recipe_id WHERE a.item_id=75008 AND a.componentcount>0 AND a.iscontainer=0 AND r.id<>2019 AND(SELECT SUM(e.componentcount)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0)=6 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=13015)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=13429)=1 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=20386)=3 AND(SELECT COALESCE(SUM(e.componentcount),0)FROM tradeskill_recipe_entries e WHERE e.recipe_id=r.id AND e.iscontainer=0 AND e.item_id=75008)=1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC209 all-state/all-skill corrected input collision'; END IF;
 IF (SELECT COUNT(*)FROM tradeskill_recipe)<>recipes_before OR(SELECT COUNT(*)FROM tradeskill_recipe_entries)<>entries_before THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC209 unexpected row-count delta'; END IF;
 DROP TEMPORARY TABLE rrc209_after;
 DROP TEMPORARY TABLE rrc209_before;
 DROP TEMPORARY TABLE rrc209_recipes;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT CONVERT(0x525243323039 USING utf8mb4) AS batch,changed_rows AS changed_rows,recipes_before,(SELECT COUNT(*)FROM tradeskill_recipe)AS recipes_after,entries_before,(SELECT COUNT(*)FROM tradeskill_recipe_entries)AS entries_after,@@in_transaction AS in_transaction;
